/*
 * MusicLibrary - the built-in music: kinds of song (Synthwave, Chase, ...) with one or more versions each.
 *
 * The audio does not ship in the DLL. MusicCatalog.cs (generated by TOR Mod\Assets\arena\build_uts_music.py)
 * names every version with its size and SHA-256; the files come from the public repository
 * DaUnknown-0/UTS-Music, and ONLY when the player asks for it: "Load music" in the music panel or the Music tab
 * of the Mod Manager. They land in BepInEx\uts-music and are checked against the catalog before they count.
 *
 * Versions: a kind shows up once in the music panel; clicking it lists its versions. The player keeps one or
 * several of them switched on ([Music] Versions); each time the kind plays, one of the switched-on versions
 * that is on this computer is drawn. Without a choice of the player, the best rated versions are on.
 * Deleting a version removes its file and remembers it ([Music] Deleted), so "Load music" leaves it out;
 * its own Download button brings it back.
 */

using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;
using BepInEx.Configuration;
using UnityEngine;
using UnityEngine.Networking;

namespace UsefulTORStuff {

    internal static partial class MusicLibrary {

        internal sealed class Kind {
            public readonly string Key, Style;
            public readonly DraftMusic.Track[] Versions;

            public Kind(string key, string style, params DraftMusic.Track[] versions) {
                Key = key;
                Style = style;
                Versions = versions;
                foreach (var v in versions) { v.KindKey = key; v.Style = style; }
            }
        }

        private static DraftMusic.Track V(string key, string title, long size, string sha256, bool best) =>
            new DraftMusic.Track { Key = key, Title = title, Size = size, Sha256 = sha256, Best = best };

        internal const string DefaultSource = "https://raw.githubusercontent.com/DaUnknown-0/UTS-Music/v1/tracks/";

        private static ConfigEntry<string> versionsCfg, deletedCfg, sourceCfg;

        internal static string Folder => Path.Combine(BepInEx.Paths.BepInExRootPath, "uts-music");
        internal static string PathOf(DraftMusic.Track t) => Path.Combine(Folder, t.Key + ".ogg");

        private static void Log(string s) => UsefulTORStuffPlugin.Logger?.LogInfo("[Music] " + s);
        private static void Warn(string s) => UsefulTORStuffPlugin.Logger?.LogWarning("[Music] " + s);

        public static void Bind(ConfigFile config) {
            versionsCfg = config.Bind("Music", "Versions", "",
                "Which versions of a kind of song are switched on, e.g. synthwave=a,c;noir=a. Kinds not listed use their "
                + "best rated versions. Easier: click a kind in the music panel.");
            deletedCfg = config.Bind("Music", "Deleted", "",
                "Versions you deleted, separated by |. Load music leaves them out; their Download button brings them back.");
            sourceCfg = config.Bind("Music", "Download source", DefaultSource,
                "Where Load music downloads from. Leave as it is.");
            foreach (var k in Kinds) foreach (var v in k.Versions) byKey[v.Key] = v;
            foreach (var k in Kinds) kindByKey[k.Key] = k;
        }

        private static readonly Dictionary<string, DraftMusic.Track> byKey = new Dictionary<string, DraftMusic.Track>();
        private static readonly Dictionary<string, Kind> kindByKey = new Dictionary<string, Kind>();

        internal static Kind KindOf(string key) => key != null && kindByKey.TryGetValue(key, out var k) ? k : null;
        internal static DraftMusic.Track Version(string key) => key != null && byKey.TryGetValue(key, out var t) ? t : null;
        internal static IEnumerable<DraftMusic.Track> AllVersions => Kinds.SelectMany(k => k.Versions);

        // ====================================================================
        // Which versions are switched on
        // ====================================================================
        private static Dictionary<string, HashSet<string>> chosen;

        private static Dictionary<string, HashSet<string>> Chosen() {
            if (chosen != null) return chosen;
            chosen = new Dictionary<string, HashSet<string>>();
            try {
                foreach (var part in (versionsCfg?.Value ?? "").Split(';', StringSplitOptions.RemoveEmptyEntries)) {
                    int eq = part.IndexOf('=');
                    if (eq <= 0) continue;
                    var kind = KindOf(part.Substring(0, eq).Trim());
                    if (kind == null) continue;
                    var set = new HashSet<string>();
                    foreach (var l in part.Substring(eq + 1).Split(',', StringSplitOptions.RemoveEmptyEntries)) {
                        string key = kind.Key + "-" + l.Trim();
                        if (byKey.ContainsKey(key)) set.Add(key);
                    }
                    if (set.Count > 0) chosen[kind.Key] = set;
                }
            } catch (Exception e) { Warn("versions: " + e.Message); }
            return chosen;
        }

        private static void SaveChosen() {
            var parts = Chosen().Select(p => p.Key + "=" + string.Join(",", p.Value.OrderBy(x => x).Select(x => x.Substring(p.Key.Length + 1))));
            try { if (versionsCfg != null) versionsCfg.Value = string.Join(";", parts); } catch { }
            DraftMusic.Changed();
        }

        internal static bool IsOn(DraftMusic.Track t) {
            if (t?.KindKey == null) return false;
            return Chosen().TryGetValue(t.KindKey, out var set) ? set.Contains(t.Key) : t.Best;
        }

        internal static int OnCount(Kind k) => k.Versions.Count(IsOn);

        /// Switches one version on or off; the last one of a kind stays on.
        internal static void Toggle(DraftMusic.Track t) {
            var kind = KindOf(t?.KindKey);
            if (kind == null) return;
            var set = new HashSet<string>(kind.Versions.Where(IsOn).Select(v => v.Key));
            if (set.Contains(t.Key)) { if (set.Count == 1) return; set.Remove(t.Key); }
            else set.Add(t.Key);
            Chosen()[kind.Key] = set;
            SaveChosen();
        }

        /// Only this version of its kind.
        internal static void Only(DraftMusic.Track t) {
            var kind = KindOf(t?.KindKey);
            if (kind == null) return;
            Chosen()[kind.Key] = new HashSet<string> { t.Key };
            SaveChosen();
        }

        // ====================================================================
        // What is on this computer
        // ====================================================================
        private static readonly Dictionary<string, bool> present = new Dictionary<string, bool>();

        /// The version's file is here and has the catalog's size (the hash was checked when it was written).
        internal static bool Ready(DraftMusic.Track t) {
            if (t == null || t.IsFile) return t != null;
            if (present.TryGetValue(t.Key, out bool p)) return p;
            try { var fi = new FileInfo(PathOf(t)); p = fi.Exists && fi.Length == t.Size; } catch { p = false; }
            present[t.Key] = p;
            return p;
        }

        internal static void Rescan() => present.Clear();

        /// A version of the kind that can play now: one that is switched on and here, else any that is here.
        internal static DraftMusic.Track Pick(Kind k, System.Random rng = null) {
            if (k == null) return null;
            var here = k.Versions.Where(v => Ready(v) && !DraftMusic.Failed(v.Key)).ToList();
            var on = here.Where(IsOn).ToList();
            var pool = on.Count > 0 ? on : here;
            if (pool.Count == 0) return null;
            return rng == null ? pool[0] : pool[rng.Next(pool.Count)];
        }

        internal static bool Playable(Kind k) => Pick(k) != null;
        internal static int ReadyCount(Kind k) => k.Versions.Count(Ready);

        // ====================================================================
        // Deleted versions
        // ====================================================================
        private static HashSet<string> deleted;

        private static HashSet<string> Deleted() {
            if (deleted != null) return deleted;
            deleted = new HashSet<string>();
            try {
                foreach (var k in (deletedCfg?.Value ?? "").Split('|', StringSplitOptions.RemoveEmptyEntries))
                    if (byKey.ContainsKey(k.Trim())) deleted.Add(k.Trim());
            } catch { }
            return deleted;
        }

        private static void SaveDeleted() {
            try { if (deletedCfg != null) deletedCfg.Value = string.Join("|", Deleted().OrderBy(x => x)); } catch { }
        }

        internal static bool IsDeleted(DraftMusic.Track t) => t != null && Deleted().Contains(t.Key);

        internal static void Delete(DraftMusic.Track t) {
            if (t == null || t.IsFile) return;
            queue.Remove(t.Key);
            state.Remove(t.Key);
            try { if (File.Exists(PathOf(t))) File.Delete(PathOf(t)); } catch (Exception e) { Warn($"delete {t.Key}: {e.Message}"); }
            present.Remove(t.Key);
            Deleted().Add(t.Key);
            SaveDeleted();
            DraftMusic.Forget(t.Key);
            Log($"{t.Key} deleted");
            DraftMusic.Changed();
        }

        /// Every downloaded version goes; "Load music" would bring them back (nothing is marked deleted).
        internal static void DeleteAll() {
            queue.Clear();
            foreach (var t in AllVersions) {
                try { if (File.Exists(PathOf(t))) File.Delete(PathOf(t)); } catch (Exception e) { Warn($"delete {t.Key}: {e.Message}"); }
                DraftMusic.Forget(t.Key);
            }
            present.Clear();
            state.Clear();
            Log("all music deleted");
            DraftMusic.Changed();
        }

        // ====================================================================
        // Downloads (only when the player asks)
        // ====================================================================
        internal enum Dl { None, Queued, Running, Failed }

        private static readonly List<string> queue = new List<string>();
        private static readonly Dictionary<string, Dl> state = new Dictionary<string, Dl>();
        private static string running;
        private static float runningProgress;
        private static bool worker;

        internal static Dl StateOf(DraftMusic.Track t) {
            if (t == null) return Dl.None;
            if (running == t.Key) return Dl.Running;
            return state.TryGetValue(t.Key, out var s) ? s : Dl.None;
        }

        internal static float Progress(DraftMusic.Track t) => t != null && running == t.Key ? runningProgress : 0f;
        internal static bool Busy => worker;
        internal static int Pending => queue.Count + (running != null ? 1 : 0);

        /// What "Load music" would fetch: everything not here and not deleted.
        internal static List<DraftMusic.Track> Missing() => AllVersions.Where(t => !Ready(t) && !IsDeleted(t)).ToList();
        internal static long Bytes(IEnumerable<DraftMusic.Track> ts) => ts.Sum(t => t.Size);
        internal static string Mb(long bytes) => Math.Max(0.1, Math.Round(bytes / 1048576.0, 1)).ToString("0.#", System.Globalization.CultureInfo.InvariantCulture);

        /// One version, also a deleted one (it is no longer deleted then).
        internal static void Download(DraftMusic.Track t) {
            if (t == null || t.IsFile) return;
            if (Deleted().Remove(t.Key)) SaveDeleted();
            Enqueue(t);
            Run();
        }

        /// "Load music": every version that is neither here nor deleted.
        internal static void DownloadAll() {
            foreach (var t in Missing()) Enqueue(t);
            Run();
        }

        private static void Enqueue(DraftMusic.Track t) {
            if (Ready(t) || running == t.Key || queue.Contains(t.Key)) return;
            queue.Add(t.Key);
            state[t.Key] = Dl.Queued;
            DraftMusic.Changed();
        }

        private static void Run() {
            if (worker || queue.Count == 0) return;
            var host = DraftMusicDriver.Instance;
            if (host == null) { Warn("no driver for downloads"); return; }
            worker = true;
            BepInEx.Unity.IL2CPP.Utils.MonoBehaviourExtensions.StartCoroutine(host, Worker());
        }

        // Only the catalog's repository, or a local test server.
        private static string Source() {
            string s = sourceCfg?.Value?.Trim() ?? DefaultSource;
            if (!s.EndsWith("/")) s += "/";
            bool ok = s.StartsWith("https://raw.githubusercontent.com/DaUnknown-0/UTS-Music/", StringComparison.Ordinal)
                      || s.StartsWith("http://127.0.0.1:", StringComparison.Ordinal);
            return ok ? s : DefaultSource;
        }

        private static IEnumerator Worker() {
            while (queue.Count > 0) {
                string key = queue[0];
                queue.RemoveAt(0);
                var t = Version(key);
                if (t == null || Ready(t)) { state.Remove(key); continue; }
                running = key;
                runningProgress = 0f;
                DraftMusic.Changed();

                var www = new UnityWebRequest();
                www.SetMethod(UnityWebRequest.UnityWebRequestMethod.Get);
                www.SetUrl(Source() + key + ".ogg");
                www.SetRequestHeader("User-Agent", $"UsefulTORStuff/{UsefulTORStuffPlugin.PluginVersion}");
                www.downloadHandler = new DownloadHandlerBuffer();
                www.timeout = 60;
                var op = www.SendWebRequest();
                int shown = -1;
                while (!op.isDone) {
                    runningProgress = www.downloadProgress;
                    int pct = Mathf.FloorToInt(runningProgress * 10f);
                    if (pct != shown) { shown = pct; DraftMusic.Changed(); }
                    yield return null;
                }
                byte[] data = null;
                string error = null;
                if (www.isNetworkError || www.isHttpError) error = $"HTTP {www.responseCode} {www.error}";
                else data = www.downloadHandler.data;
                www.downloadHandler.Dispose();
                www.Dispose();

                if (error == null) {
                    var write = Task.Run(() => Store(t, data));
                    while (!write.IsCompleted) yield return null;
                    error = write.IsFaulted ? write.Exception?.GetBaseException().Message : write.Result;
                }
                running = null;
                present.Remove(key);
                if (error == null) { state.Remove(key); Log($"{key} downloaded ({t.Size} bytes)"); }
                else { state[key] = Dl.Failed; Warn($"{key}: download failed ({error})"); }
                DraftMusic.Changed();
            }
            worker = false;
            DraftMusic.Changed();
        }

        // Worker thread: size and SHA-256 against the catalog, then write beside and move into place.
        private static string Store(DraftMusic.Track t, byte[] data) {
            if (data == null || data.Length != t.Size) return $"size {data?.Length ?? 0} instead of {t.Size}";
            string hash;
            using (var sha = SHA256.Create()) hash = BitConverter.ToString(sha.ComputeHash(data)).Replace("-", "").ToLowerInvariant();
            if (hash != t.Sha256) return "checksum does not match";
            Directory.CreateDirectory(Folder);
            string path = PathOf(t), tmp = path + ".part";
            File.WriteAllBytes(tmp, data);
            if (File.Exists(path)) File.Delete(path);
            File.Move(tmp, path);
            return null;
        }
    }
}
